import { CanActivate, ExecutionContext, Injectable, SetMetadata } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

import type { RequestUser } from './jwt-auth.guard';

export const PORTAL_METADATA_KEY = 'memories:required-portal';

/** e.g. `@RequirePortal('ADMIN')` on a controller/route. Plain string, not identity-access's
 * `Portal` enum — `libs/platform/security` must not depend on a business module (module boundary,
 * `npm run test:architecture`). */
export const RequirePortal = (portal: string) => SetMetadata(PORTAL_METADATA_KEY, portal);

/**
 * §13/§23: a token issued for one portal must not be treated as valid for another — "Token public
 * không thể truy cập admin API nếu không hợp lệ về audience hoặc portal". Run after `JwtAuthGuard`
 * (needs `request.user.portal`, populated from the `portal` JWT claim) and before `PermissionsGuard`
 * — a PUBLIC-portal token must be rejected here even if the underlying Account also happens to hold
 * admin permissions, since that Account never authenticated *into* the admin portal for this session.
 */
@Injectable()
export class PortalGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredPortal = this.reflector.getAllAndOverride<string>(PORTAL_METADATA_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!requiredPortal) {
      return true;
    }

    const request = context.switchToHttp().getRequest<{ user?: RequestUser }>();
    return request.user?.portal === requiredPortal;
  }
}

