1	import { AsyncLocalStorage } from 'node:async_hooks';
2	
3	import { Injectable } from '@nestjs/common';
4	
5	/**
6	 * Actor/request metadata threaded through a single request's async call chain (§14). Roles and
7	 * permissions are mutable arrays on the same store object — `RequestContextMiddleware` seeds an
8	 * empty store before any guard runs; `JwtAuthGuard`/`PermissionsGuard` enrich the SAME object
9	 * in place once they resolve the caller, rather than starting a new `AsyncLocalStorage.run`, so
10	 * every layer downstream (use cases, repositories, audit metadata) observes the same reference.
11	 * A `null` `accountId` means "no authenticated Account" (anonymous request or system actor);
12	 * `isSystemActor` distinguishes worker/scheduler/CLI background execution from an anonymous HTTP
13	 * caller (both have `accountId: null`).
14	 */
15	export interface RequestContextStore {
16	  requestId: string;
17	  correlationId: string;
18	  accountId: string | null;
19	  userProfileId: string | null;
20	  sessionId: string | null;
21	  portal: string | null;
22	  authProvider: string | null;
23	  roles: string[];
24	  permissions: string[];
25	  ipAddress: string | null;
26	  userAgent: string | null;
27	  requestedAt: Date;
28	  isSystemActor: boolean;
29	}
30	
31	/** Same shape as `Partial<RequestContextStore>`, but each key explicitly allows `undefined` so
32	 * callers built with `exactOptionalPropertyTypes` can pass through possibly-undefined values
33	 * (e.g. `correlation?.requestId`) without first stripping the key. */
34	type RequestContextOverrides = {
35	  [K in keyof RequestContextStore]?: RequestContextStore[K] | undefined;
36	};
37	
38	export function createEmptyRequestContextStore(
39	  overrides: RequestContextOverrides = {},
40	): RequestContextStore {
41	  return {
42	    requestId: overrides.requestId ?? crypto.randomUUID(),
43	    correlationId: overrides.correlationId ?? overrides.requestId ?? crypto.randomUUID(),
44	    accountId: overrides.accountId ?? null,
45	    userProfileId: overrides.userProfileId ?? null,
46	    sessionId: overrides.sessionId ?? null,
47	    portal: overrides.portal ?? null,
48	    authProvider: overrides.authProvider ?? null,
49	    roles: overrides.roles ?? [],
50	    permissions: overrides.permissions ?? [],
51	    ipAddress: overrides.ipAddress ?? null,
52	    userAgent: overrides.userAgent ?? null,
53	    requestedAt: overrides.requestedAt ?? new Date(),
54	    isSystemActor: overrides.isSystemActor ?? false,
55	  };
56	}
57	
58	@Injectable()
59	export class RequestContext {
60	  private static readonly storage = new AsyncLocalStorage<RequestContextStore>();
61	
62	  run<TResult>(store: RequestContextStore, callback: () => TResult): TResult {
63	    return RequestContext.storage.run(store, callback);
64	  }
65	
66	  get(): RequestContextStore | undefined {
67	    return RequestContext.storage.getStore();
68	  }
69	
70	  /** The actor id to stamp on audit columns: the authenticated Account, or `null` for anonymous/
71	   * system actors — never throws, since not every write happens inside an authenticated request
72	   * (seeders, background jobs). */
73	  currentActorId(): string | null {
74	    return RequestContext.storage.getStore()?.accountId ?? null;
75	  }
76	
77	  /** Runs `work` under a synthetic system-actor context (worker/scheduler/CLI, §14) so audit
78	   * columns and correlation IDs are still populated outside of any HTTP request. */
79	  runAsSystem<TResult>(callback: () => TResult, correlationId?: string): TResult {
80	    return this.run(
81	      createEmptyRequestContextStore({ isSystemActor: true, correlationId }),
82	      callback,
83	    );
84	  }
85	}
