import { AuthConfig } from '@memories/platform/configuration';
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { JwtService } from '@nestjs/jwt';

import { IssuedToken, TokenClaims, TokenService } from './token.contract';

@Injectable()
export class JwtTokenService implements TokenService {
  constructor(
    private readonly jwtService: JwtService,
    private readonly configService: ConfigService,
  ) {}

  async issueAccessToken(claims: TokenClaims): Promise<IssuedToken> {
    const auth = this.configService.getOrThrow<AuthConfig>('auth');
    return this.sign(claims, auth.jwt.accessSecret, auth.jwt.accessTtl);
  }

  async issueRefreshToken(claims: TokenClaims): Promise<IssuedToken> {
    const auth = this.configService.getOrThrow<AuthConfig>('auth');
    return this.sign(claims, auth.jwt.refreshSecret, auth.jwt.refreshTtl);
  }

  async verifyAccessToken(token: string): Promise<TokenClaims> {
    const auth = this.configService.getOrThrow<AuthConfig>('auth');
    return this.jwtService.verifyAsync<TokenClaims>(token, { secret: auth.jwt.accessSecret });
  }

  async verifyRefreshToken(token: string): Promise<TokenClaims> {
    const auth = this.configService.getOrThrow<AuthConfig>('auth');
    return this.jwtService.verifyAsync<TokenClaims>(token, { secret: auth.jwt.refreshSecret });
  }

  private async sign(claims: TokenClaims, secret: string, expiresIn: string): Promise<IssuedToken> {
    const token = await this.jwtService.signAsync(claims, { secret, expiresIn });
    return { token, expiresAt: new Date(Date.now() + msFromDuration(expiresIn)) };
  }
}

function msFromDuration(duration: string): number {
  const match = /^(\d+)(s|m|h|d)$/.exec(duration);
  if (!match) {
    return 0;
  }
  const value = Number(match[1]);
  const unit = match[2];
  const unitMs = { s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 }[unit as 's' | 'm' | 'h' | 'd'];
  return value * unitMs;
}

