import { TypeOrmQueryRunnerContext } from '@memories/platform/database';
import { UniqueEntityId } from '@memories/shared/kernel';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { IsNull, Repository as TypeOrmRepository } from 'typeorm';

import { RefreshSession } from '../../domain/sessions/refresh-session';
import { RefreshSessionRepository } from '../../domain/sessions/refresh-session.repository';

import { RefreshSessionMapper } from './refresh-session.mapper';
import { RefreshSessionOrmEntity } from './refresh-session.orm-entity';

@Injectable()
export class TypeOrmRefreshSessionRepository implements RefreshSessionRepository {
  private readonly mapper = new RefreshSessionMapper();

  constructor(
    @InjectRepository(RefreshSessionOrmEntity)
    private readonly repository: TypeOrmRepository<RefreshSessionOrmEntity>,
    private readonly queryRunnerContext: TypeOrmQueryRunnerContext,
  ) {}

  private repositoryFor(): TypeOrmRepository<RefreshSessionOrmEntity> {
    const queryRunner = this.queryRunnerContext.get();
    return queryRunner ? queryRunner.manager.getRepository(RefreshSessionOrmEntity) : this.repository;
  }

  async findById(id: UniqueEntityId): Promise<RefreshSession | null> {
    const raw = await this.repositoryFor().findOne({ where: { id: id.toValue() } });
    return raw ? this.mapper.toDomain(raw) : null;
  }

  async save(aggregate: RefreshSession): Promise<void> {
    await this.repositoryFor().save(this.mapper.toPersistence(aggregate));
  }

  async delete(id: UniqueEntityId): Promise<void> {
    await this.repositoryFor().delete({ id: id.toValue() });
  }

  async revokeAllForAccount(accountId: string, now: Date): Promise<number> {
    const result = await this.repositoryFor().update(
      { accountId, revokedAt: IsNull() },
      { revokedAt: now },
    );
    return result.affected ?? 0;
  }
}

