2	import {
3	  CLOCK,
4	  Clock,
5	  DomainError,
6	  UniqueEntityId,
7	  UnitOfWork,
8	  UseCase,
9	} from '@memories/shared/kernel';
10	import { Inject, Injectable } from '@nestjs/common';
11	
12	import { ACCOUNT_REPOSITORY, AccountRepository } from '../../domain/accounts/account.repository';
13	import {
14	  AUTH_IDENTITY_REPOSITORY,
15	  AuthIdentityRepository,
16	} from '../../domain/auth-identities/auth-identity.repository';
17	import { AuthProvider } from '../../domain/auth-identities/auth-provider';
18	import {
19	  REFRESH_SESSION_REPOSITORY,
20	  RefreshSessionRepository,
21	} from '../../domain/sessions/refresh-session.repository';
22	import { PASSWORD_HASHER, PasswordHasher } from '../ports/password-hasher.port';
23	
24	export interface ChangeAccountPasswordInput {
25	  accountId: string;
26	  newPassword: string;
27	  actorId: string | null;
28	}
29	
30	/** §16 `PATCH /accounts/:accountId/password` (also used for admin-triggered reset). Revokes every
31	 * outstanding session and bumps `Account.tokenVersion` (§13) — standard hygiene after a password
32	 * change/reset, forcing re-login everywhere else the Account is currently signed in. */
33	@Injectable()
34	export class ChangeAccountPasswordUseCase implements UseCase<ChangeAccountPasswordInput, void> {
35	  constructor(
36	    @Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository,
37	    @Inject(AUTH_IDENTITY_REPOSITORY) private readonly authIdentities: AuthIdentityRepository,
38	    @Inject(REFRESH_SESSION_REPOSITORY) private readonly refreshSessions: RefreshSessionRepository,
39	    @Inject(PASSWORD_HASHER) private readonly passwordHasher: PasswordHasher,
40	    @Inject(UNIT_OF_WORK) private readonly unitOfWork: UnitOfWork,
41	    @Inject(CLOCK) private readonly clock: Clock,
42	  ) {}
43	
44	  async execute(input: ChangeAccountPasswordInput): Promise<void> {
45	    await this.unitOfWork.withTransaction(async () => {
46	      const now = this.clock.now();
47	
48	      const account = await this.accounts.findById(new UniqueEntityId(input.accountId));
49	      if (!account) {
50	        throw DomainError.notFound('account_not_found', `Account ${input.accountId} was not found`);
51	      }
52	
53	      const identities = await this.authIdentities.findAllByAccountId(input.accountId);
54	      const localIdentity = identities.find((identity) => identity.provider === AuthProvider.Local);
55	      if (!localIdentity) {
56	        throw DomainError.notFound(
57	          'local_auth_identity_not_found',
58	          `Account ${input.accountId} has no LOCAL auth identity`,
59	        );
60	      }
61	
62	      const passwordHash = await this.passwordHasher.hash(input.newPassword);
63	      localIdentity.changePasswordHash(passwordHash, input.actorId, now);
64	      await this.authIdentities.save(localIdentity);
65	
66	      account.incrementTokenVersion(input.actorId, now);
67	      await this.accounts.save(account);
68	
69	      await this.refreshSessions.revokeAllForAccount(input.accountId, now);
70	    });
71	  }
72	}
