12	
13	export const PERMISSIONS_METADATA_KEY = 'memories:required-permissions';
14	
15	/** e.g. RequirePermissions('orders:read', 'orders:refund') on a controller method. */
16	export const RequirePermissions = (...permissions: string[]) =>
17	  SetMetadata(PERMISSIONS_METADATA_KEY, permissions);
18	
