20	  roles: string[];
21	  permissions: string[];
22	}
23	
24	/** Implemented by identity-access; other modules only see this port through DI. */
25	export interface PermissionChecker {
26	  hasPermissions(userId: string, permissions: string[]): Promise<boolean>;
27	  /** Full role/permission resolution for the request context (§14) — used by `PermissionsGuard`
28	   * to populate `RequestContext.roles`/`.permissions` even on routes that don't declare
29	   * `@RequirePermissions(...)`, so downstream code (audit, business rules) can still read "what
30	   * can this caller do" without a second round-trip. */
31	  resolvePermissions(userId: string): Promise<ResolvedPermissions>;
32	}
33	
34	export const PERMISSION_CHECKER = Symbol('PERMISSION_CHECKER');
35	
36	@Injectable()
37	export class PermissionsGuard implements CanActivate {
38	  constructor(
39	    private readonly reflector: Reflector,
40	    @Inject(PERMISSION_CHECKER) private readonly permissionChecker: PermissionChecker,
41	    @Optional() private readonly requestContext?: RequestContext,
42	  ) {}
43	
44	  async canActivate(context: ExecutionContext): Promise<boolean> {
45	    const required = this.reflector.getAllAndOverride<string[]>(PERMISSIONS_METADATA_KEY, [
46	      context.getHandler(),
47	      context.getClass(),
48	    ]);
49	
50	    const request = context.switchToHttp().getRequest<{ user?: { id: string } }>();
51	    if (!request.user) {
52	      return !required || required.length === 0;
53	    }
54	
55	    const store = this.requestContext?.get();
56	    if (store && store.accountId === request.user.id && store.roles.length === 0) {
57	      const resolved = await this.permissionChecker.resolvePermissions(request.user.id);
58	      store.roles = resolved.roles;
59	      store.permissions = resolved.permissions;
60	    }
61	
62	    if (!required || required.length === 0) {
63	      return true;
64	    }
65	
66	    return this.permissionChecker.hasPermissions(request.user.id, required);
67	  }
68	}
