import {
  CanActivate,
  ExecutionContext,
  Inject,
  Injectable,
  Optional,
  SetMetadata,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';

import { RequestContext } from './request-context';

export const PERMISSIONS_METADATA_KEY = 'memories:required-permissions';

/** e.g. RequirePermissions('orders:read', 'orders:refund') on a controller method. */
export const RequirePermissions = (...permissions: string[]) =>
  SetMetadata(PERMISSIONS_METADATA_KEY, permissions);

export interface ResolvedPermissions {
  roles: string[];
  permissions: string[];
}

/** Implemented by identity-access; other modules only see this port through DI. */
export interface PermissionChecker {
  hasPermissions(userId: string, permissions: string[]): Promise<boolean>;
  /** Full role/permission resolution for the request context (§14) — used by `PermissionsGuard`
   * to populate `RequestContext.roles`/`.permissions` even on routes that don't declare
   * `@RequirePermissions(...)`, so downstream code (audit, business rules) can still read "what
   * can this caller do" without a second round-trip. */
  resolvePermissions(userId: string): Promise<ResolvedPermissions>;
}

export const PERMISSION_CHECKER = Symbol('PERMISSION_CHECKER');

@Injectable()
export class PermissionsGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    @Inject(PERMISSION_CHECKER) private readonly permissionChecker: PermissionChecker,
    @Optional() private readonly requestContext?: RequestContext,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const required = this.reflector.getAllAndOverride<string[]>(PERMISSIONS_METADATA_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);

    const request = context.switchToHttp().getRequest<{ user?: { id: string } }>();
    if (!request.user) {
      return !required || required.length === 0;
    }

    const store = this.requestContext?.get();
    if (store && store.accountId === request.user.id && store.roles.length === 0) {
      const resolved = await this.permissionChecker.resolvePermissions(request.user.id);
      store.roles = resolved.roles;
      store.permissions = resolved.permissions;
    }

    if (!required || required.length === 0) {
      return true;
    }

    return this.permissionChecker.hasPermissions(request.user.id, required);
  }
}

