1	import {
2	  AggregateRoot,
3	  AuditableProps,
4	  DomainError,
5	  UniqueEntityId,
6	} from '@memories/shared/kernel';
7	
8	export interface UserProfileProps extends AuditableProps {
9	  accountId: string;
10	  fullName: string;
11	  /** Contact info only — never a login identifier (task.md §4 "Email không được sử dụng làm login
12	   * identifier"); always normalized to lowercase before persisting. */
13	  email: string | null;
14	  avatarId: string | null;
15	  dateOfBirth: Date | null;
16	  address: string | null;
17	}
18	
19	/**
20	 * The single shared profile for an Account (task.md §4). Holds personal data only — no password,
21	 * no permission — and never a TypeORM relation to `Account` (module boundary, task.md §4/§1):
22	 * `accountId` is a plain string FK, existence/status checked through `AccountLookup`.
23	 */
24	export class UserProfile extends AggregateRoot<UserProfileProps> {
25	  static create(props: UserProfileProps, id?: UniqueEntityId): UserProfile {
26	    if (!props.fullName.trim()) {
27	      throw DomainError.validation('full_name_required', 'UserProfile requires a full name');
28	    }
29	    return new UserProfile(props, id);
30	  }
31	
32	  get accountId(): string {
33	    return this.props.accountId;
34	  }
35	
36	  get fullName(): string {
37	    return this.props.fullName;
38	  }
39	
40	  get email(): string | null {
41	    return this.props.email;
42	  }
43	
44	  get avatarId(): string | null {
45	    return this.props.avatarId;
46	  }
47	
48	  get dateOfBirth(): Date | null {
49	    return this.props.dateOfBirth;
50	  }
51	
52	  get address(): string | null {
53	    return this.props.address;
54	  }
55	
56	  get audit(): AuditableProps {
57	    return this.props;
58	  }
59	
60	  get isDeleted(): boolean {
61	    return this.props.deletedAt !== null;
62	  }
63	
64	  update(
65	    changes: {
66	      fullName?: string | undefined;
67	      email?: string | null | undefined;
68	      avatarId?: string | null | undefined;
69	      dateOfBirth?: Date | null | undefined;
70	      address?: string | null | undefined;
71	    },
72	    actorId: string | null,
73	    now: Date,
74	  ): void {
75	    if (changes.fullName !== undefined) {
76	      if (!changes.fullName.trim()) {
77	        throw DomainError.validation('full_name_required', 'UserProfile requires a full name');
78	      }
79	      this.props.fullName = changes.fullName;
80	    }
81	    if (changes.email !== undefined) {
82	      this.props.email = changes.email;
83	    }
84	    if (changes.avatarId !== undefined) {
85	      this.props.avatarId = changes.avatarId;
86	    }
87	    if (changes.dateOfBirth !== undefined) {
88	      this.props.dateOfBirth = changes.dateOfBirth;
89	    }
90	    if (changes.address !== undefined) {
91	      this.props.address = changes.address;
92	    }
93	    this.touch(actorId, now);
94	  }
95	
96	  softDelete(actorId: string | null, now: Date): void {
97	    if (this.isDeleted) {
98	      throw DomainError.conflict(
99	        'user_profile_already_deleted',
100	        `UserProfile ${this._id.toString()} is already deleted`,
101	      );
102	    }
103	    this.props.deletedBy = actorId;
104	    this.props.deletedAt = now;
105	    this.touch(actorId, now);
106	  }
107	
108	  private touch(actorId: string | null, now: Date): void {
109	    this.props.updatedBy = actorId;
110	    this.props.updatedAt = now;
111	  }
