import { DomainError, UniqueEntityId, UseCase } from '@memories/shared/kernel';
import { Inject, Injectable } from '@nestjs/common';

import { USER_PROFILE_REPOSITORY, UserProfileRepository } from '../../domain/user-profile.repository';

import { toOutput, UserProfileOutput } from './create-user-profile.use-case';

export interface GetUserProfileInput {
  userProfileId: string;
}

@Injectable()
export class GetUserProfileUseCase implements UseCase<GetUserProfileInput, UserProfileOutput> {
  constructor(@Inject(USER_PROFILE_REPOSITORY) private readonly userProfiles: UserProfileRepository) {}

  async execute(input: GetUserProfileInput): Promise<UserProfileOutput> {
    const profile = await this.userProfiles.findById(new UniqueEntityId(input.userProfileId));
    if (!profile) {
      throw DomainError.notFound('user_profile_not_found', `UserProfile ${input.userProfileId} was not found`);
    }
    return toOutput(profile);
  }
}

