import { SecurityConfig } from '@memories/platform/configuration';
import { DynamicModule, MiddlewareConsumer, Module, NestModule } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { APP_GUARD } from '@nestjs/core';
import { JwtModule } from '@nestjs/jwt';
import { ThrottlerGuard, ThrottlerModule } from '@nestjs/throttler';

import { JwtTokenService } from './jwt-token.service';
import { RequestContext } from './request-context';
import { RequestContextMiddleware } from './request-context.middleware';
import { TOKEN_SERVICE } from './token.contract';

@Module({})
export class SecurityModule implements NestModule {
  static register(): DynamicModule {
    return {
      module: SecurityModule,
      global: true,
      imports: [
        JwtModule.register({}),
        ThrottlerModule.forRootAsync({
          inject: [ConfigService],
          useFactory: (configService: ConfigService) => {
            const security = configService.getOrThrow<SecurityConfig>('security');
            return [
              { ttl: security.rateLimit.ttlSeconds * 1000, limit: security.rateLimit.maxRequests },
            ];
          },
        }),
      ],
      providers: [
        { provide: TOKEN_SERVICE, useClass: JwtTokenService },
        // `ThrottlerModule.forRootAsync` above only registers the RATE_LIMIT_* configuration —
        // it does not, by itself, make anything enforce it. `APP_GUARD` is NestJS's own token for
        // registering a guard globally regardless of which module provides it, so every HTTP
        // request across every controller in any app that imports this module (only apps/api has
        // controllers with real inbound HTTP traffic; the guard is simply never invoked for
        // apps/worker/scheduler/cli/realtime, which have none) is actually throttled — without
        // this, RATE_LIMIT_TTL_SECONDS/RATE_LIMIT_MAX_REQUESTS had no effect at all.
        { provide: APP_GUARD, useClass: ThrottlerGuard },
        RequestContext,
        RequestContextMiddleware,
      ],
      exports: [TOKEN_SERVICE, ThrottlerModule, RequestContext],
    };
  }

  static registerAsync(): DynamicModule {
    return SecurityModule.register();
  }

  /** Runs after `ObservabilityModule`'s `CorrelationMiddleware` (import order in `app.module.ts`
   * puts Observability before Security), so `RequestContextMiddleware` can read the correlation
   * IDs it already established for this request. */
  configure(consumer: MiddlewareConsumer): void {
    consumer.apply(RequestContextMiddleware).forRoutes('*');
  }
}

