import { SeedRolesAndPermissionsUseCase } from '@memories/modules/identity-access';
import { Injectable, Logger } from '@nestjs/common';

import { CliCommand } from './command.contract';

/** `npm run start:cli -- seed`. Business modules register their own seed logic as they gain
 * persistence models — identity-access's Role/Permission seed (task.md §7/§12) is the first one. */
@Injectable()
export class SeedCommand implements CliCommand {
  readonly name = 'seed';
  private readonly logger = new Logger(SeedCommand.name);

  constructor(private readonly seedRolesAndPermissions: SeedRolesAndPermissionsUseCase) {}

  async run(): Promise<void> {
    await this.seedRolesAndPermissions.execute();
    this.logger.log('Seeded identity-access roles and permissions.');
  }
}

