1	/**
2	 * Cross-cutting ports that let `identity-access` and `user-profiles` compose (Account creation
3	 * must provision a UserProfile in the same transaction; UserProfile CRUD must check the owning
4	 * Account exists/is active) WITHOUT either module importing the other's `public-api.ts` — same
5	 * shape as `PermissionChecker` below: each port is implemented by one module and consumed by DI
6	 * only, so the module dependency graph stays acyclic (`npm run test:architecture`).
7	 */
8	
9	/** Implemented by identity-access; consumed by user-profiles (and anything else needing to check
10	 * an Account is real/usable before acting on data keyed by `accountId`). */
11	export interface AccountLookup {
12	  exists(accountId: string): Promise<boolean>;
13	  isActive(accountId: string): Promise<boolean>;
14	}
15	
16	export const ACCOUNT_LOOKUP = Symbol('ACCOUNT_LOOKUP');
17	
18	/** Implemented by identity-access; consumed by user-profiles' list query (task.md §17 "Search
19	 * phone thông qua identity-access query contract") so it never queries `identity.auth_identities`
20	 * directly. */
