import { Repository, UniqueEntityId } from '@memories/shared/kernel';

import { Account } from './account';
import { AccountStatus } from './account-status';

export interface AccountListFilter {
  status?: AccountStatus | undefined;
  /** Matches an `AuthIdentity.provider` the account has (e.g. `LOCAL`). */
  provider?: string | undefined;
  /** Substring match against the account's LOCAL phone identifier. */
  phoneSearch?: string | undefined;
  page: number;
  pageSize: number;
  sortBy: 'createdAt' | 'updatedAt';
  sortDirection: 'ASC' | 'DESC';
}

export interface AccountListItem {
  account: Account;
  phone: string | null;
}

export interface AccountRepository extends Repository<Account> {
  /** `findById` (from `Repository<Account>`) excludes soft-deleted rows — this variant is for the
   * few flows (e.g. idempotency checks) that must still see a deleted Account. */
  findByIdIncludingDeleted(id: UniqueEntityId): Promise<Account | null>;
  list(filter: AccountListFilter): Promise<{ items: AccountListItem[]; total: number }>;
}

export const ACCOUNT_REPOSITORY = Symbol('ACCOUNT_REPOSITORY');

/** Only `Local` is fully implemented in this epic; the others exist so the schema/contract
 * (`AuthenticationProvider` port + registry) doesn't need to change shape when they're added
 * (task.md §11 "Google, Apple và Facebook chỉ cần contract và provider code"). */
export enum AuthProvider {
  Local = 'LOCAL',
  Google = 'GOOGLE',
  Apple = 'APPLE',
  Facebook = 'FACEBOOK',
}

import { ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { IsEnum, IsIn, IsInt, IsOptional, IsString, Max, Min } from 'class-validator';

import { AccountStatus } from '../../domain/accounts/account-status';

export class ListAccountsQueryDto {
  @ApiPropertyOptional({ enum: AccountStatus })
  @IsOptional()
  @IsEnum(AccountStatus)
  status?: AccountStatus;

  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  provider?: string;

  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  phone?: string;

  @ApiPropertyOptional({ default: 1 })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @ApiPropertyOptional({ default: 20 })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  pageSize = 20;

  @ApiPropertyOptional({ enum: ['createdAt', 'updatedAt'], default: 'createdAt' })
  @IsOptional()
  @IsIn(['createdAt', 'updatedAt'])
  sortBy: 'createdAt' | 'updatedAt' = 'createdAt';

  @ApiPropertyOptional({ enum: ['ASC', 'DESC'], default: 'DESC' })
  @IsOptional()
  @IsIn(['ASC', 'DESC'])
  sortDirection: 'ASC' | 'DESC' = 'DESC';
}

