import { ACCOUNT_LOOKUP, ACCOUNT_PHONE_SEARCH, PERMISSION_CHECKER } from '@memories/platform/security';
import { CLOCK, ID_GENERATOR, SystemClock, UuidGenerator } from '@memories/shared/kernel';
import { Global, Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';

import { AuthenticationProviderRegistry, AUTHENTICATION_PROVIDERS } from './application/ports/authentication-provider.port';
import { PASSWORD_HASHER } from './application/ports/password-hasher.port';
import { PHONE_NORMALIZER } from './application/ports/phone-normalizer.port';
