/**
 * Identity & Access bounded context (task.md — Account/AuthIdentity/RefreshSession/Role/Permission/
 * portal authorization). Marked `@Global()` for the same reason as `UserProfilesModule`: it
 * implements several cross-cutting ports declared in `@memories/platform/security`
 * (`PERMISSION_CHECKER`, `ACCOUNT_LOOKUP`, `ACCOUNT_PHONE_SEARCH`) that most other business modules
 * need (any controller using `@RequirePermissions`), without every one of them adding this module
 * to their own `imports`.
 */
@Global()
@Module({
  imports: [
    TypeOrmModule.forFeature([
      AccountOrmEntity,
      AuthIdentityOrmEntity,
      RefreshSessionOrmEntity,
      RoleOrmEntity,
      PermissionOrmEntity,
      AccountRoleOrmEntity,
      RolePermissionOrmEntity,
    ]),
  ],
  controllers: [AuthController, AccountController],
  providers: [
    CreateAccountUseCase,
    DeleteAccountUseCase,
    LoginUseCase,
    LogoutUseCase,
    RefreshSessionUseCase,
    ChangeAccountPasswordUseCase,
    ChangeAccountPhoneUseCase,
    ChangeAccountStatusUseCase,
    GetAccountUseCase,
    ListAccountsUseCase,
    UpdateAccountUseCase,
    SeedRolesAndPermissionsUseCase,
    { provide: ACCOUNT_REPOSITORY, useClass: TypeOrmAccountRepository },
    { provide: AUTH_IDENTITY_REPOSITORY, useClass: TypeOrmAuthIdentityRepository },
    { provide: REFRESH_SESSION_REPOSITORY, useClass: TypeOrmRefreshSessionRepository },
    { provide: ROLE_REPOSITORY, useClass: TypeOrmRoleRepository },
    { provide: PERMISSION_REPOSITORY, useClass: TypeOrmPermissionRepository },
    { provide: ACCOUNT_ROLE_REPOSITORY, useClass: TypeOrmAccountRoleRepository },
    { provide: ROLE_PERMISSION_REPOSITORY, useClass: TypeOrmRolePermissionRepository },
    { provide: PASSWORD_HASHER, useClass: ScryptPasswordHasher },
    { provide: PHONE_NORMALIZER, useClass: PhoneNormalizer },
    { provide: PERMISSION_CHECKER, useClass: PermissionCheckerService },
    { provide: ACCOUNT_LOOKUP, useClass: AccountLookupService },
    { provide: ACCOUNT_PHONE_SEARCH, useClass: AccountPhoneSearchService },
    { provide: ID_GENERATOR, useClass: UuidGenerator },
    { provide: CLOCK, useClass: SystemClock },
    LocalAuthenticationProvider,
    {
      provide: AUTHENTICATION_PROVIDERS,
      useFactory: (local: LocalAuthenticationProvider) => [local],
      inject: [LocalAuthenticationProvider],
    },
    {
      provide: AuthenticationProviderRegistry,
      useFactory: (providers: LocalAuthenticationProvider[]) => new AuthenticationProviderRegistry(providers),
      inject: [AUTHENTICATION_PROVIDERS],
    },
  ],
  exports: [PERMISSION_CHECKER, ACCOUNT_LOOKUP, ACCOUNT_PHONE_SEARCH, SeedRolesAndPermissionsUseCase],
})
export class IdentityAccessModule {}

