import { Mapper, UniqueEntityId } from '@memories/shared/kernel';

import { RefreshSession } from '../../domain/sessions/refresh-session';

import { RefreshSessionOrmEntity } from './refresh-session.orm-entity';

export class RefreshSessionMapper implements Mapper<RefreshSession, RefreshSessionOrmEntity> {
  toDomain(raw: RefreshSessionOrmEntity): RefreshSession {
    return RefreshSession.create(
      {
        accountId: raw.accountId,
        portal: raw.portal,
        authProvider: raw.authProvider,
        ipAddress: raw.ipAddress,
        userAgent: raw.userAgent,
        issuedAt: raw.issuedAt,
        expiresAt: raw.expiresAt,
        revokedAt: raw.revokedAt,
        replacedBySessionId: raw.replacedBySessionId,
      },
      new UniqueEntityId(raw.id),
    );
  }

  toPersistence(domain: RefreshSession): RefreshSessionOrmEntity {
    const entity = new RefreshSessionOrmEntity();
    entity.id = domain.id.toValue();
    entity.accountId = domain.accountId;
    entity.portal = domain.portal;
    entity.authProvider = domain.authProvider;
    entity.expiresAt = domain.expiresAt;
    entity.revokedAt = domain.revokedAt;
    entity.ipAddress = domain.ipAddress;
    entity.userAgent = domain.userAgent;
    entity.issuedAt = domain.issuedAt;
    entity.replacedBySessionId = domain.replacedBySessionId;
    return entity;
  }

  toDto(domain: RefreshSession) {
    return { id: domain.id.toValue(), portal: domain.portal };
  }
}

