import { createAuditableProps, UniqueEntityId } from '@memories/shared/kernel';
import { ForbiddenException } from '@nestjs/common';

import { AuthenticationProviderRegistry } from '../src/application/ports/authentication-provider.port';
import { LoginUseCase } from '../src/application/use-cases/login.use-case';
import { Account } from '../src/domain/accounts/account';
import { AccountStatus } from '../src/domain/accounts/account-status';
import { AuthProvider } from '../src/domain/auth-identities/auth-provider';
import { Portal } from '../src/domain/sessions/portal';

const NOW = new Date('2026-01-01T00:00:00Z');

function buildAccount(status = AccountStatus.Active): Account {
  return Account.create(
    { status, tokenVersion: 0, ...createAuditableProps(null, NOW) },
    new UniqueEntityId('account-1'),
  );
}

function buildUseCase(overrides: { localAuthenticate?: jest.Mock } = {}) {
  const accounts = { findById: jest.fn() };
  const refreshSessions = { save: jest.fn() };
  const permissionChecker = { hasPermissions: jest.fn(), resolvePermissions: jest.fn() };
  const userProfileLookup = { findProfileIdByAccountId: jest.fn().mockResolvedValue('profile-1') };
  const tokenService = {
    issueAccessToken: jest.fn().mockResolvedValue({ token: 'access-token', expiresAt: NOW }),
    issueRefreshToken: jest.fn().mockResolvedValue({
      token: 'refresh-token',
      expiresAt: new Date('2026-02-01T00:00:00Z'),
    }),
  };
  const phoneNormalizer = { normalize: jest.fn().mockReturnValue({ value: '+84912345678' }) };
  const unitOfWork = { withTransaction: jest.fn((work: () => unknown) => work()) };
  const idGenerator = { generate: jest.fn().mockReturnValue('session-1') };
  const clock = { now: () => NOW };
  const localAuthenticate =
    overrides.localAuthenticate ?? jest.fn().mockResolvedValue({ accountId: 'account-1', authIdentityId: 'identity-1' });
  const authenticationProviders = new AuthenticationProviderRegistry([
    { provider: AuthProvider.Local, authenticate: localAuthenticate },
  ]);
  const configService = { getOrThrow: jest.fn().mockReturnValue({ phone: { defaultRegion: 'VN' } }) };

  const useCase = new LoginUseCase(
    accounts as never,
    refreshSessions as never,
    permissionChecker as never,
    userProfileLookup as never,
    tokenService as never,
    phoneNormalizer as never,
    unitOfWork as never,
    idGenerator as never,
    clock as never,
    authenticationProviders,
    configService as never,
  );

  return { useCase, accounts, refreshSessions, permissionChecker, tokenService, localAuthenticate };
}

describe('LoginUseCase', () => {
  it('issues tokens and creates a portal-scoped RefreshSession when credential + portal permission are valid', async () => {
    const { useCase, accounts, refreshSessions, permissionChecker, tokenService } = buildUseCase();
    accounts.findById.mockResolvedValue(buildAccount());
    permissionChecker.hasPermissions.mockResolvedValue(true);
    permissionChecker.resolvePermissions.mockResolvedValue({
      roles: ['ADMIN'],
      permissions: ['portal.admin.access'],
    });

    const result = await useCase.execute({
      phone: '0912345678',
      password: 'correct-password',
      portal: Portal.Admin,
      ipAddress: null,
      userAgent: null,
    });

    expect(permissionChecker.hasPermissions).toHaveBeenCalledWith('account-1', ['portal.admin.access']);
    expect(tokenService.issueAccessToken).toHaveBeenCalledWith(
