/**
 * Cross-cutting ports that let `identity-access` and `user-profiles` compose (Account creation
 * must provision a UserProfile in the same transaction; UserProfile CRUD must check the owning
 * Account exists/is active) WITHOUT either module importing the other's `public-api.ts` — same
 * shape as `PermissionChecker` below: each port is implemented by one module and consumed by DI
 * only, so the module dependency graph stays acyclic (`npm run test:architecture`).
 */

/** Implemented by identity-access; consumed by user-profiles (and anything else needing to check
 * an Account is real/usable before acting on data keyed by `accountId`). */
export interface AccountLookup {
  exists(accountId: string): Promise<boolean>;
  isActive(accountId: string): Promise<boolean>;
}

export const ACCOUNT_LOOKUP = Symbol('ACCOUNT_LOOKUP');

/** Implemented by identity-access; consumed by user-profiles' list query (task.md §17 "Search
 * phone thông qua identity-access query contract") so it never queries `identity.auth_identities`
 * directly. */
export interface AccountPhoneSearch {
  /** Account IDs whose LOCAL phone identifier contains `search`. */
  searchAccountIdsByPhone(search: string): Promise<string[]>;
}

export const ACCOUNT_PHONE_SEARCH = Symbol('ACCOUNT_PHONE_SEARCH');

/** Implemented by user-profiles; consumed by identity-access (login needs `userProfileId` for the
 * JWT payload, §13). */
export interface UserProfileLookup {
  findProfileIdByAccountId(accountId: string): Promise<string | null>;
}

export const USER_PROFILE_LOOKUP = Symbol('USER_PROFILE_LOOKUP');

export interface ProvisionUserProfileInput {
  accountId: string;
  fullName: string;
  email?: string | undefined;
  dateOfBirth?: Date | undefined;
  address?: string | undefined;
  avatarId?: string | undefined;
  actorId: string | null;
}

export interface ProvisionUserProfileOutput {
  userProfileId: string;
}

/** Implemented by user-profiles; consumed by identity-access's account-creation transaction
 * (§8 step 6 — "Tạo UserProfile" — must happen in the same `UnitOfWork.withTransaction` as the
 * Account/AuthIdentity/AccountRole writes) and its delete-account transaction (§16 "Xóa Account
 * phải: ... Soft delete UserProfile"). */
export interface UserProfileProvisioner {
  provision(input: ProvisionUserProfileInput): Promise<ProvisionUserProfileOutput>;
  deleteByAccountId(accountId: string, actorId: string | null): Promise<void>;
}

export const USER_PROFILE_PROVISIONER = Symbol('USER_PROFILE_PROVISIONER');

