import { RefreshSession } from './refresh-session';

export interface RefreshSessionRepository extends Repository<RefreshSession> {
  /** Revokes every currently-active session for the account (§13 "Account bị khóa hoặc xóa phải
   * revoke toàn bộ session"), regardless of portal/device. Returns the number of rows revoked. */
