/** `pg`/TypeORM hydrates a `date`-typed column as a plain `YYYY-MM-DD` string (there is no
 * time-of-day to parse it against), not a `Date` — but `UserProfileProps.dateOfBirth` and every
 * caller (`UserProfileMapper`, `UserProfileController#toResponseDto`'s `.toISOString()`) are typed
 * and written as `Date`. Without this transformer, every read of a profile with a birth date set
 * hands the domain layer a `string` with a `Date`'s type but none of its methods, and the response
 * mapper throws `TypeError: dateOfBirth.toISOString is not a function`. Normalizing to UTC midnight
 * keeps the value stable across round-trips (`to` receives a `Date` from the domain and stores only
 * its date part; `from` reconstructs the same calendar day regardless of server-local timezone). */
const dateOnlyTransformer: ValueTransformer = {
  to: (value: Date | null): string | null => (value ? value.toISOString().slice(0, 10) : null),
  from: (value: string | null): Date | null => (value ? new Date(`${value}T00:00:00.000Z`) : null),
};

