/**
 * Cross-cutting ports that let `identity-access` and `user-profiles` compose (Account creation
 * must provision a UserProfile in the same transaction; UserProfile CRUD must check the owning
 * Account exists/is active) WITHOUT either module importing the other's `public-api.ts` — same
 * shape as `PermissionChecker` below: each port is implemented by one module and consumed by DI
 * only, so the module dependency graph stays acyclic (`npm run test:architecture`).
 */

export interface AccountAuthState {
  isActive: boolean;
  /** Current `Account.tokenVersion` — an already-issued access token whose embedded `tokenVersion`
   * claim no longer matches this must be rejected (password change / forced logout, §13). */
  tokenVersion: number;
}

/** Implemented by identity-access; consumed by user-profiles (and anything else needing to check
 * an Account is real/usable before acting on data keyed by `accountId`). */
export interface AccountLookup {
  exists(accountId: string): Promise<boolean>;
  isActive(accountId: string): Promise<boolean>;
  /** Single round-trip status+tokenVersion read for `JwtAuthGuard` (§19 "Protected request kiểm
   * tra Account status") — `null` when the account doesn't exist or is soft-deleted. */
  getAuthState(accountId: string): Promise<AccountAuthState | null>;
}

