import { DomainError } from '@memories/shared/kernel';

import { CreateAccountUseCase } from '../src/application/use-cases/create-account.use-case';
import { Role } from '../src/domain/roles/role';

const NOW = new Date('2026-01-01T00:00:00Z');

function buildUseCase(overrides: { currentActorId?: string | null } = {}) {
  const accounts = { save: jest.fn() };
  const authIdentities = {
    existsByProviderAndIdentifier: jest.fn().mockResolvedValue(false),
    save: jest.fn(),
  };
  const accountRoles = { assign: jest.fn() };
  const roles = {
    findByCode: jest.fn().mockResolvedValue(
      Role.create({ code: 'PUBLIC_USER', name: 'Public User', createdBy: null, createdAt: NOW, updatedBy: null, updatedAt: NOW, deletedBy: null, deletedAt: null }),
    ),
  };
  const passwordHasher = { hash: jest.fn().mockResolvedValue('hashed-password') };
  const phoneNormalizer = { normalize: jest.fn().mockReturnValue({ value: '+84912345678' }) };
  const userProfileProvisioner = { provision: jest.fn().mockResolvedValue({ userProfileId: 'profile-1' }) };
  const idGenerator = { generate: jest.fn().mockReturnValueOnce('account-1').mockReturnValueOnce('identity-1') };
  const clock = { now: () => NOW };
  const unitOfWork = { withTransaction: jest.fn((work: () => unknown) => work()) };
  const configService = {
    getOrThrow: jest.fn().mockReturnValue({
      phone: { defaultRegion: 'VN' },
      defaultRole: { code: 'PUBLIC_USER' },
    }),
  };
  const requestContext = {
    currentActorId: jest.fn().mockReturnValue(overrides.currentActorId ?? 'admin-account-1'),
  };

  const useCase = new CreateAccountUseCase(
    unitOfWork as never,
    accounts as never,
    authIdentities as never,
    accountRoles as never,
    roles as never,
    passwordHasher as never,
    phoneNormalizer as never,
    userProfileProvisioner as never,
    idGenerator as never,
    clock as never,
    configService as never,
    requestContext as never,
  );

  return { useCase, accounts, authIdentities, accountRoles, userProfileProvisioner, requestContext };
}

describe('CreateAccountUseCase', () => {
  it('stamps every created aggregate/grant with the actor resolved from the ambient RequestContext', async () => {
    const { useCase, accounts, authIdentities, accountRoles, userProfileProvisioner, requestContext } =
      buildUseCase({ currentActorId: 'admin-account-1' });

    await useCase.execute({ phone: '0912345678', password: 'Sup3rSecret!', fullName: 'A' });

    expect(requestContext.currentActorId).toHaveBeenCalled();
    expect(accounts.save).toHaveBeenCalledWith(
      expect.objectContaining({ audit: expect.objectContaining({ createdBy: 'admin-account-1' }) }),
    );
    expect(authIdentities.save).toHaveBeenCalledWith(
      expect.objectContaining({ audit: expect.objectContaining({ createdBy: 'admin-account-1' }) }),
    );
    expect(accountRoles.assign).toHaveBeenCalledWith('account-1', expect.any(String), 'admin-account-1', NOW);
    // No `actorId` is threaded through the cross-module provision call — the input has no such
    // field at all (`ProvisionUserProfileInput` doesn't declare one); the provisioner resolves the
    // actor independently from the same ambient RequestContext.
    expect(userProfileProvisioner.provision).toHaveBeenCalledWith(
      expect.not.objectContaining({ actorId: expect.anything() }),
    );
  });

  it('stamps a null actor for an unauthenticated self-registration (no RequestContext store)', async () => {
    const { useCase, accounts } = buildUseCase({ currentActorId: null });

    await useCase.execute({ phone: '0912345678', password: 'Sup3rSecret!', fullName: 'A' });

    expect(accounts.save).toHaveBeenCalledWith(
      expect.objectContaining({ audit: expect.objectContaining({ createdBy: null }) }),
    );
  });

  it('rolls back without provisioning a profile or assigning a role when the phone is already registered', async () => {
    const { useCase, authIdentities, accountRoles, userProfileProvisioner } = buildUseCase();
    authIdentities.existsByProviderAndIdentifier.mockResolvedValue(true);

    await expect(
      useCase.execute({ phone: '0912345678', password: 'Sup3rSecret!', fullName: 'A' }),
    ).rejects.toThrow(DomainError);
    expect(accountRoles.assign).not.toHaveBeenCalled();
    expect(userProfileProvisioner.provision).not.toHaveBeenCalled();
  });
});

